-- 0016: more fuel and clothes (docs/GEAR.md §11). Two more gels (caffeine,
-- red; race, gold), two more foods (rice cake, recovery shake) and three more
-- kits. The fuel kinds now live only in gear_rules(): use_gel() already
-- refuses any kind that isn't there, so the table's kind check goes.

alter table public.user_boosts drop constraint if exists user_boosts_kind_check;

